def update_standard_choices(apps, schema_editor):
    """Change standard content only; existing player history stays untouched."""
    from django.conf import settings

    using = schema_editor.connection.alias
    Slot = apps.get_model("library", "Slot")
    Pickable = apps.get_model("library", "Pickable")
    Modifier = apps.get_model("library", "Modifier")
    GangType = apps.get_model("library", "GangType")
    slot = (
        Slot.objects.using(using)
        .filter(
            name="Escape", qualifier="", pack__slug=settings.DEFAULT_CONTENT_PACK_SLUG
        )
        .first()
    )
    if slot is None:
        return
    Slot.objects.using(using).filter(pk=slot.pk).update(follows_status=True)
    captures = Pickable.objects.using(using).filter(
        pack_id=slot.pack_id,
        name="Captured",
        slot_type__name__in=["Lasting Injury", "Lasting Damage"],
    )
    captures.update(record_only=True)
    for result in captures:
        result.modifiers.remove(
            *result.modifiers.using(using).filter(adds_assignable__slot_id=slot.pk)
        )
    Pickable.objects.using(using).filter(
        pack_id=slot.pack_id, slot_type_id=slot.slot_type_id
    ).update(record_only=True)
    modifier = (
        Modifier.objects.using(using)
        .filter(pack_id=slot.pack_id, name="Captured models: Escape")
        .first()
    )
    if modifier is None:
        scope = (
            apps.get_model("library", "TargetsMiniature")
            .objects.using(using)
            .create(reach="every_model")
        )
        apps.get_model("library", "HasStatus").objects.using(using).create(
            scope_id=scope.pk, status="captured"
        )
        effect = (
            apps.get_model("library", "AddsAssignable")
            .objects.using(using)
            .create(slot_id=slot.pk)
        )
        modifier = Modifier.objects.using(using).create(
            name="Captured models: Escape",
            pack_id=slot.pack_id,
            targets_miniature_id=scope.pk,
            adds_assignable_id=effect.pk,
        )
    for gang_type in GangType.objects.using(using).filter(pack_id=slot.pack_id):
        gang_type.modifiers.add(modifier)


